This is a greedy placement with a time-bounded search. I have not compiled or run it, and I did not tune it against any data set.

**Approach**

1. Keep an occupancy grid for the city. For each utility type, keep a coverage grid. A cell is marked covered when it lies within distance D of a placed utility of that type.
2. Candidate placements are every position where a building fits and its occupied cells don't overlap anything already placed.
3. For a residential building, the score is its capacity times the number of utility types that cover it. A utility only helps through the residential buildings near it.
4. Greedy phases:
   - Pick the residential project with the best capacity per occupied cell (ratio) and tile the city densely with it, row by row, in scan order.
   - Then try to put utilities into the leftover free space. Utility types are placed to maximise the number of residential buildings that gain a new type.
5. Interleaved pattern, which is simpler and robust: process the placed residential buildings first, then fill free cells with utility buildings. To keep this cheap, test each placement quickly by bounding-box overlap checks.

**Simplified implementation**

- Pick the best residential project R by capacity divided by occupied cell count.
- Pick the utility project U with the fewest occupied cells, and for tiling choose the one with the best area and shape.
- Build a periodic pattern: place rows of R and U alternately in scan order. For each position in row-major order, try R first and place it if it fits. Every k-th placement uses a utility of rotating type instead, so each residential building has many types within D.
- Try several values of k (and of how many utility types to use) and evaluate each full layout by exact scoring. Keep the best.
- Exact scoring is a brute-force check. For each residential building, loop over utility buildings and compute the bounding-box-aware minimum distance with early exit. With at most about 1e6 cells and up to a few thousand buildings, this is affordable for a handful of trials.
- Scoring uses the exact minimum Manhattan distance between occupied cells. To keep that cheap, I compute the distance on bounding boxes as a lower bound, and skip the pair if the lower bound is greater than D. Otherwise I do a cell-by-cell check.

```cpp
#include <bits/stdc++.h>
using namespace std;
struct P{bool res;int h,w,v;vector<string> g;vector<pair<int,int>> cells;};
int H,W,D,B;
vector<P> ps;
struct Pl{int b,r,c;};
bool fits(vector<vector<char>>&occ,const P&p,int r,int c){
    if(r+p.h>H||c+p.w>W)return false;
    for(auto&q:p.cells)if(occ[r+q.first][c+q.second])return false;
    return true;
}
void put(vector<vector<char>>&occ,const P&p,int r,int c){
    for(auto&q:p.cells)occ[r+q.first][c+q.second]=1;
}
long long score(const vector<Pl>&v){
    vector<int> R,U;
    for(int i=0;i<(int)v.size();i++){if(ps[v[i].b].res)R.push_back(i);else U.push_back(i);}
    long long s=0;
    for(int i:R){
        const P&a=ps[v[i].b];
        set<int> t;
        for(int j:U){
            const P&b=ps[v[j].b];
            if(t.count(b.v))continue;
            int ar=v[i].r,ac=v[i].c,br=v[j].r,bc=v[j].c;
            int dr=max(0,max(ar-(br+b.h-1),br-(ar+a.h-1)));
            int dc=max(0,max(ac-(bc+b.w-1),bc-(ac+a.w-1)));
            if(dr+dc>D)continue;
            bool ok=false;
            for(auto&x:a.cells){
                for(auto&y:b.cells){
                    if(abs(ar+x.first-br-y.first)+abs(ac+x.second-bc-y.second)<=D){ok=true;break;}
                }
                if(ok)break;
            }
            if(ok)t.insert(b.v);
        }
        s+=(long long)a.v*t.size();
    }
    return s;
}
int main(){
    scanf("%d %d %d %d",&H,&W,&D,&B);
    ps.resize(B);
    for(auto&p:ps){
        char t;scanf(" %c %d %d %d",&t,&p.h,&p.w,&p.v);
        p.res=(t=='R');
        p.g.resize(p.h);
        for(int i=0;i<p.h;i++){
            char buf[64];scanf("%s",buf);p.g[i]=buf;
            for(int j=0;j<p.w;j++)if(buf[j]=='#')p.cells.push_back({i,j});
        }
    }
    int bestR=-1;double br=-1;
    for(int i=0;i<B;i++)if(ps[i].res){
        double r=(double)ps[i].v/ps[i].cells.size();
        if(r>br){br=r;bestR=i;}
    }
    // utility per type: smallest cell count
    map<int,int> ut;
    for(int i=0;i<B;i++)if(!ps[i].res){
        auto it=ut.find(ps[i].v);
        if(it==ut.end()||ps[i].cells.size()<ps[it->second].cells.size())ut[ps[i].v]=i;
    }
    vector<int> U;
    vector<pair<size_t,int>> tmp;
    for(auto&k:ut)tmp.push_back({ps[k.second].cells.size(),k.second});
    sort(tmp.begin(),tmp.end());
    for(auto&k:tmp)U.push_back(k.second);
    vector<Pl> best;long long bs=-1;
    int maxU=min<int>(U.size(),4);
    auto start=chrono::steady_clock::now();
    for(int nu=1;nu<=maxU;nu++){
        for(int k=2;k<=6;k++){
            if(chrono::duration<double>(chrono::steady_clock::now()-start).count()>6.0)break;
            vector<vector<char>> occ(H,vector<char>(W,0));
            vector<Pl> v;int cnt=0,ui=0;
            for(int r=0;r<H;r++)for(int c=0;c<W;c++){
                bool useU=(cnt%k==k-1);
                int b=useU?U[ui%nu]:bestR;
                if(fits(occ,ps[b],r,c)){
                    put(occ,ps[b],r,c);v.push_back({b,r,c});
                    cnt++;if(useU)ui++;
                }
            }
            if(v.size()>6000)continue;
            long long s=score(v);
            if(s>bs){bs=s;best=v;}
        }
    }
    if(bs<0){
        // fallback: one residential and one utility
        vector<vector<char>> occ(H,vector<char>(W,0));
        int u=U[0];
        for(int r=0;r<H&&best.size()<2;r++)for(int c=0;c<W&&best.size()<2;c++){
            int b=best.empty()?bestR:u;
            if(fits(occ,ps[b],r,c)){put(occ,ps[b],r,c);best.push_back({b,r,c});}
        }
    }
    printf("%d\n",(int)best.size());
    for(auto&p:best)printf("%d %d %d\n",p.b,p.r,p.c);
}
```

**Caveats**

- If a layout has more than 6000 buildings, I skip it so the scoring step stays fast. That means large cities with small buildings may only get the fallback layout, which is a weak result.
- The fallback places one residential and one utility, so it is valid but low-scoring.
